// HomePage.js
import React from "react";

function HomePage() {
  return (
    <div style={styles.container}>
      {/* Navbar */}
      <nav style={styles.navbar}>
        <h2 style={styles.logo}>Smart Queue System</h2>

        <div>
          <button style={styles.loginBtn}>Login</button>
          <button style={styles.registerBtn}>Register</button>
        </div>
      </nav>

      {/* Hero Section */}
      <div style={styles.hero}>
        <div style={styles.left}>
          <h1 style={styles.heading}>
            Welcome to Smart Queue System
          </h1>

          <p style={styles.text}>
            Skip long waiting lines and manage queues smartly.
            Book your slot online and save your time easily.
          </p>

          <button style={styles.bookBtn}>
            Book Queue
          </button>
        </div>

        <div style={styles.right}>
          <img
            src="https://cdn-icons-png.flaticon.com/512/2784/2784487.png"
            alt="queue"
            style={styles.image}
          />
        </div>
      </div>

      {/* Features */}
      <div style={styles.features}>
        <div style={styles.card}>
          <h3>Online Booking</h3>
          <p>Book your queue slot anytime.</p>
        </div>

        <div style={styles.card}>
          <h3>Live Queue Status</h3>
          <p>Check real-time queue updates.</p>
        </div>

        <div style={styles.card}>
          <h3>Save Time</h3>
          <p>No more standing in long lines.</p>
        </div>
      </div>

      {/* Footer */}
      <footer style={styles.footer}>
        <p>© 2026 Smart Queue System</p>
      </footer>
    </div>
  );
}

const styles = {
  container: {
    fontFamily: "Arial",
    backgroundColor: "#f5f7fa",
    minHeight: "100vh",
  },

  navbar: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "15px 40px",
    backgroundColor: "#1e3a8a",
    color: "white",
  },

  logo: {
    margin: 0,
  },

  loginBtn: {
    marginRight: "10px",
    padding: "10px 18px",
    border: "none",
    borderRadius: "5px",
    cursor: "pointer",
  },

  registerBtn: {
    padding: "10px 18px",
    border: "none",
    borderRadius: "5px",
    backgroundColor: "#f59e0b",
    color: "white",
    cursor: "pointer",
  },

  hero: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "60px 80px",
    flexWrap: "wrap",
  },

  left: {
    maxWidth: "500px",
  },

  heading: {
    fontSize: "45px",
    color: "#1e3a8a",
  },

  text: {
    fontSize: "18px",
    color: "#555",
    lineHeight: "1.6",
  },

  bookBtn: {
    marginTop: "20px",
    padding: "12px 25px",
    backgroundColor: "#2563eb",
    color: "white",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
    fontSize: "16px",
  },

  right: {
    marginTop: "20px",
  },

  image: {
    width: "320px",
  },

  features: {
    display: "flex",
    justifyContent: "center",
    gap: "25px",
    padding: "40px",
    flexWrap: "wrap",
  },

  card: {
    backgroundColor: "white",
    padding: "25px",
    width: "250px",
    borderRadius: "10px",
    boxShadow: "0px 4px 10px rgba(0,0,0,0.1)",
    textAlign: "center",
  },

  footer: {
    textAlign: "center",
    padding: "20px",
    backgroundColor: "#1e3a8a",
    color: "white",
    marginTop: "30px",
  },
};

export default HomePage;
